package com.booksyde.service; import com.booksyde.exception.BusinessException; import java.net.URI; import java.net.http.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; @Service public class ResendEmailService {private final String key,from; private final HttpClient http=HttpClient.newHttpClient(); public ResendEmailService(@Value("${booksyde.resend.api-key:}")String k,@Value("${booksyde.resend.from:}")String f){key=k;from=f;} public void send(String to,String subject,String html){if(key.isBlank())throw new BusinessException("Resend não configurado."); try{String json="{\"from\":\""+esc(from)+"\",\"to\":[\""+esc(to)+"\"],\"subject\":\""+esc(subject)+"\",\"html\":\""+esc(html)+"\"}";var req=HttpRequest.newBuilder(URI.create("https://api.resend.com/emails")).header("Authorization","Bearer "+key).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(json)).build();var r=http.send(req,HttpResponse.BodyHandlers.ofString());if(r.statusCode()/100!=2)throw new BusinessException("Falha ao enviar e-mail.");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new BusinessException("Envio de e-mail interrompido.");}catch(Exception e){if(e instanceof BusinessException b)throw b;throw new BusinessException("Falha ao enviar e-mail.");}} private String esc(String s){return s.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n");}}